      const manifest = yaml.parse(await fs.readFile(manifestPath, 'utf-8'));

      for (const skill of manifest.skills) {
        const skillMdPath = path.join(PACKAGE_ROOT, 'plugin', 'plugins', 'kspec', 'skills', skill.id, 'SKILL.md');
