      const content = await fs.readFile(manifestPath, 'utf-8');
      expect(content).toContain('skills:');
    });

    it('help skill has SKILL.md content', async () => {
      const skillMdPath = path.join(PACKAGE_ROOT, 'templates', 'skills', 'help', 'SKILL.md');
