      const packageJsonPath = path.join(PACKAGE_ROOT, 'package.json');
      const pkg = JSON.parse(await fs.readFile(packageJsonPath, 'utf-8'));
      expect(kspecPlugin.version).toBe(pkg.version);
    });
  });
});

