function spawnRalphUntil(
  args: string[],
  marker: string,
  env: Record<string, string> = {},
): Promise<{ output: string }> {
  return new Promise((resolve, reject) => {
    const child = nodeSpawn("node", [CLI_PATH, "ralph", ...args], {
      cwd: tempDir,
      env: {
        ...process.env,
        KSPEC_SPEC_DIR: tempDir,
        KSPEC_AUTHOR: "@test",
        ...env,
      },
      stdio: ["pipe", "pipe", "pipe"],
    });

    let output = "";
    let resolved = false;

    const onData = (d: Buffer) => {
      output += d.toString();
      // Once we see the marker, cleanup is done — give a small grace period then kill
      if (!resolved && output.includes(marker)) {
        resolved = true;
        setTimeout(() => {
          child.kill("SIGKILL");
          resolve({ output });
        }, 500);
      }
    };
    child.stdout!.on("data", onData);
    child.stderr!.on("data", onData);

    child.on("close", () => {
      if (!resolved) {
        resolved = true;
        resolve({ output });
      }
    });

    // Safety timeout
    setTimeout(() => {
      if (!resolved) {
        resolved = true;
        child.kill("SIGKILL");
        reject(new Error(`Timed out waiting for marker "${marker}"\noutput: ${output}`));
      }
    }, 25_000);
  });
}

